let addinExtensions = dynamic([".xll", ".xla", ".xlam"]);
let xlstartPaths = dynamic(["C:\\Program Files\\Microsoft Office\\root\\Office16\\XLSTART", "C:\\Users\\<username>\\AppData\\Roaming\\Microsoft\\Excel\\XLSTART"]);
DeviceFileEvents
| where FolderPath in (xlstartPaths)
| where FileName has ".xll" or FileName has ".xla" or FileName has ".xlam"
| project TimeGenerated, FileName, FolderPath, InitiatingProcessFileName, InitiatingProcessAccountName

// Parameters
let identityinfo_window = 14d;
let lookback = 2h;
let security_info_actions = dynamic([
  "User registered security info",
  "User changed default security info",
  "User deleted security info",
  "Admin updated security info",
  "User reviewed security info",
  "Admin deleted security info",
  "Admin registered security info"
]);
// Build VIP list (safer for dynamic arrays via mv-expand)
let VIPUsers = 
    IdentityInfo
    | where TimeGenerated > ago(identityinfo_window)
    | mv-expand AssignedRoles
    | where tostring(AssignedRoles) contains "Admin"   // adjust to specific role names if you have them
    | summarize by AccountUPN;
// Main query
AuditLogs
| where TimeGenerated > ago(lookback)
| where Category =~ "UserManagement"
| where ActivityDisplayName in (security_info_actions)
| extend InitiatingAppName = tostring(InitiatedBy.app.displayName)
| extend InitiatingAppServicePrincipalId = tostring(InitiatedBy.app.servicePrincipalId)
| extend InitiatingUserPrincipalName = tostring(InitiatedBy.user.userPrincipalName)
| extend InitiatingAadUserId = tostring(InitiatedBy.user.id)
| extend InitiatingIpAddress = tostring(iff(isnotempty(InitiatedBy.user.ipAddress), InitiatedBy.user.ipAddress, InitiatedBy.app.ipAddress))
// Expand targets safely
| mv-apply TargetResource = TargetResources on
    (
        where TargetResource.type =~ "User"
        | extend TargetUserPrincipalName = tostring(TargetResource.userPrincipalName),
                 TargetAadUserId = tostring(TargetResource.id)
    )
// Optional: limit to specific logging service
// | where LoggedByService =~ "Authentication Methods"
| where TargetUserPrincipalName in~ (VIPUsers)
// ----- Choose one of the two output modes below -----
// (A) RAW events (comment out this block if you prefer summaries)
| project TimeGenerated, ActivityDisplayName, Result, ResultReason,
          InitiatingAppName, InitiatingAppServicePrincipalId,
          InitiatingUserPrincipalName, InitiatingAadUserId, InitiatingIpAddress,
          TargetUserPrincipalName, TargetAadUserId,
          // convenience splits
          InitiatingAccountName = tostring(split(InitiatingUserPrincipalName, "@")[0]),
          InitiatingAccountUPNSuffix = tostring(split(InitiatingUserPrincipalName, "@")[1]),
          TargetAccountName = tostring(split(TargetUserPrincipalName, "@")[0]),
          TargetAccountUPNSuffix = tostring(split(TargetUserPrincipalName, "@")[1])
// (B) If you prefer summarized view, replace the project above with:
// | summarize Start=min(TimeGenerated), End=max(TimeGenerated),
//             Actions = make_set(ResultReason, MaxSize=8)
//   by ActivityDisplayName, Result,
//      InitiatingAppName, InitiatingAppServicePrincipalId,
//      InitiatingUserPrincipalName, InitiatingAadUserId, InitiatingIpAddress,
//      TargetUserPrincipalName

