properties.query:
// Lookback matches queryPeriod
let lookback = 24h;
// Extract user UPN + phone number from AuditLogs where user profile/auth methods changed
let UserPhoneChanges =
  AuditLogs
  | where TimeGenerated > ago(lookback)
  | where Result =~ "success"
  // Common patterns observed when auth details/phone are updated. Keep if your original filters are preferred.
  | where Identity =~ "Azure Credential Configuration Endpoint Service" or Category =~ "UserManagement"
  | where OperationName =~ "Update user" or ActivityDisplayName has_any ("registered security info", "updated security info", "authentication method")
  // Expand targets and properties to locate phone number fields
  | mv-expand TR = TargetResources
  | extend UserPrincipalName = tostring(TR.userPrincipalName)
  | mv-expand MP = TR.modifiedProperties
  | where isnotempty(MP)
  | extend MPDisplay = tostring(MP.displayName),
           NewValue  = tostring(MP.newValue)
  // Focus on strong auth / phone related properties
  | where tolower(MPDisplay) has_any ("strongauthentication", "phone", "phonemethod", "telephone")
  // Parse JSON newValue which may be an object or array of objects
  | extend Parsed = parse_json(NewValue)
  | extend PhoneCandidate =
    case(
      // Check if it's an array and has elements
      isnotnull(array_length(Parsed)) and array_length(Parsed) > 0,
          coalesce(tostring(Parsed[0].PhoneNumber), tostring(Parsed[0].phoneNumber)),
      // Check if it's a single object
      isnotnull(Parsed.PhoneNumber) or isnotnull(Parsed.phoneNumber),
          coalesce(tostring(Parsed.PhoneNumber), tostring(Parsed.phoneNumber)),
      // Fallback: regex extraction
      extract(@"(\+?\d[\d\s\-()]{6,})", 1, NewValue)
    )
  | where isnotempty(UserPrincipalName) and isnotempty(PhoneCandidate)
  | project TimeGenerated, UserPrincipalName, PhoneNumber = trim(@'\s', tostring(PhoneCandidate));
// Find phone numbers used by more than one user
let DuplicatedPhones =
  UserPhoneChanges
  | summarize Users = make_set(UserPrincipalName), UsersCount = dcount(UserPrincipalName) by PhoneNumber
  | where UsersCount > 1
  | extend UsersCsv = strcat_array(Users, ", ");
// Emit one row per affected user for entity mapping
UserPhoneChanges
| join kind=inner (DuplicatedPhones) on PhoneNumber
| extend AccountName = tostring(split(UserPrincipalName, "@")[0]),
         AccountUPNSuffix = iif(array_length(split(UserPrincipalName, "@")) >= 2, tostring(split(UserPrincipalName, "@")[1]), "")
| project
    TimeGenerated,
    UserPrincipalName,
    PhoneNumber,
    UsersCsv,
    UsersCount,
    AccountName,
    AccountUPNSuffix

