properties.query:
// =====================================
// SYSTEM-level LOLBin activity that writes risky files to user-writable paths
// =====================================
let Lookback = 5h;
let SuspiciousExt = dynamic([
  ".exe",".dll",".js",".vbs",".hta",".ps1",".bat",".cmd",
  ".lnk",".cpl",".scr",".jar",".iso",".img"
]);
// Maintainable allowlists
let AllowedParents = dynamic([
  "serviceshell.exe","wavessyssvc64.exe","nvmup.exe","sre.exe","expressconnect.exe",
  "cursor.exe","intel-ppm-provisioning-package_d6rt2_win64_8.0.0_a00_03.exe",
  "cmd.exe","msiexec.exe","mpcmdrun.exe","code.exe","_conda.exe"
]);
let AllowedCmdRegex = dynamic([
  @"^cmd\.exe\s+/c\s+copy\s+/y\s+c:[\\]programdata[\\].*[\\]expressconnect[\\].*\s+.*>\s*nul$",
  @"^cmd\.exe\s+/c\s+.*[\\]windows[\\]temp[\\]_is[0-9a-f]+\.tmp.*$",
  @"^cursor\.exe.*--type=(crashpad-handler|gpu-process|utility).*$",
  @"^code\.exe.*--type=(crashpad-handler|gpu-process|utility|renderer).*$",
  @"^expand(\.exe)?\s+.*[\\]programdata[\\]dell[\\]supportassist[\\].*$",
  @"^certutil\.exe\s+-f\s+-addstore\s+(""|')?dell trust(""|')?\s+.*\.cer$",
  @"^cmd\.exe\s+/c.*fsutil\.exe\s+usn\s+queryjournal\s+c:.*$"
]);
let Lolbins = dynamic([
  "cmd.exe","certutil.exe","bitsadmin.exe","expand.exe",
  "rundll32.exe","regsvr32.exe","mshta.exe","wscript.exe",
  "cscript.exe","powershell.exe"
]);

// --------------- Core SYSTEM LOLBin selection + suppressions ----------------
let LolbinBase =
(
  DeviceProcessEvents
  | where TimeGenerated > ago(Lookback)
  | where AccountSid == 'S-1-5-18'  // LocalSystem
  // Normalize
  | extend
      file   = tolower(FileName),
      parent = tolower(InitiatingProcessFileName),
      cmd    = tolower(ProcessCommandLine),
      folder = tolower(FolderPath),
      ipath  = tolower(InitiatingProcessFolderPath)
  // Scope to real LOLBins
  | where file in~ (Lolbins)
  // Behavior indicators of LOLBin abuse (basic verbs and common LOLBin usage)
  | where cmd matches regex @"\b(copy|move|echo|type|certutil|bitsadmin|expand|rundll32|regsvr32|mshta|wscript|cscript|powershell(\.exe)?\s+-enc|powershell(\.exe)?\s+new-item|cmd\.exe\s+/c)\b"
  // User-writable touchpoints
  | where cmd has_any ("c:/users/","/appdata/","/windows/temp/","/programdata/","/downloads/")
  // ---------- High-volume benign suppressions ----------
  // A) rundll32 child helpers from Chromium/Electron
  | where not (file == "rundll32.exe" and cmd matches regex @"--type=(renderer|gpu-process|utility|crashpad-handler)")
  // B) MSI custom actions invoking rundll32
  | where not (file == "rundll32.exe" and parent == "msiexec.exe" and cmd matches regex @"(customactions|[\\]windows[\\]temp[\\]_is[0-9a-f]+\.tmp|sfxca)")
  // C) certutil store seeding from msiexec
  | where not (file == "certutil.exe" and parent == "msiexec.exe" and cmd matches regex @"-addstore\s+(""|')?dell trust(""|')?")
  // D) Defender Support diagnostic (MpCmdRun -> fsutil usn queryjournal)
  | where not (file == "cmd.exe" and parent == "mpcmdrun.exe" and cmd has "fsutil.exe usn queryjournal")
  // ---------- Your allowlist model ----------
  // (1) cmd.exe child with trusted parent
  | where not (file == "cmd.exe" and parent in (AllowedParents))
  // (2) Parent trusted AND command-line matches an allowed pattern
  | extend AllowedCmdHit =
      (cmd matches regex tostring(AllowedCmdRegex[0])) or
      (cmd matches regex tostring(AllowedCmdRegex[1])) or
      (cmd matches regex tostring(AllowedCmdRegex[2])) or
      (cmd matches regex tostring(AllowedCmdRegex[3])) or
      (cmd matches regex tostring(AllowedCmdRegex[4])) or
      (cmd matches regex tostring(AllowedCmdRegex[5])) or
      (cmd matches regex tostring(AllowedCmdRegex[6]))
  | where not (parent in (AllowedParents) and AllowedCmdHit)
  // Keep columns needed for join/triage
  | project
      TimeGenerated, DeviceId, ProcessId, InitiatingProcessAccountSid,
      DeviceName, FileName, FolderPath, ProcessCommandLine,
      InitiatingProcessFileName, InitiatingProcessFolderPath
);

// ---------------- Join only when it writes risky files ----------------
LolbinBase
| join kind=inner (
    DeviceFileEvents
    | where TimeGenerated > ago(Lookback)
    | where ActionType in~ ("FileCreated","FileModified","FileRenamed")
    // Compute target extension
    | extend TargetExt = tolower(strcat('.', extract(@"\.([a-z0-9]+)$", 1, FileName)))
    | where TargetExt in~ (SuspiciousExt)
    // User-writable locations guard
    | extend fpath = tolower(FolderPath)
    | where fpath has_any ("c:/users/","/appdata/","/windows/temp/","/programdata/","/downloads/")
    | project
        DeviceId,
        InitiatingProcessAccountSid,
        InitiatingProcessId,
        FileEventTime = TimeGenerated,
        TargetFile = FolderPath,
        FileAction = ActionType,
        TargetExt
  )
  on DeviceId, $left.ProcessId == $right.InitiatingProcessId, InitiatingProcessAccountSid
| project-away InitiatingProcessId
| project
    TimeGenerated,
    FileEventTime,
    DeviceName,
    FileName,
    FolderPath,
    ProcessCommandLine,
    InitiatingProcessFileName,
    InitiatingProcessFolderPath,
    TargetFile,
    TargetExt,
    FileAction
| order by FileEventTime desc, TimeGenerated desc

